import{z as o,x as d,o as e,c as l,q as A,j as B,D as E,d as r,s as n,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"DRAM 刷新","description":"","frontmatter":{"title":"DRAM 刷新","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dram-refresh.md","filePath":"cs/dram-refresh.md","lastUpdated":1791413859000}'),p={name:"cs/dram-refresh.md"};function m(D,a,C,h,c,u){const t=d("Mermaid");return e(),l("div",null,[a[2]||(a[2]=A('<h1 id="dram-刷新" tabindex="-1">DRAM 刷新 <a class="header-anchor" href="#dram-刷新" aria-label="Permalink to &quot;DRAM 刷新&quot;">​</a></h1><div class="epigraph"><p>电容上的电荷会漏；必须在保留时间内把每一行读出再写回，否则比特自己消失，与 CPU 有没有访存无关。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>钉死了 1T1C 与破坏性读。本课不重画字线位线，也不从文件系统掉电另起。缺口是把「必须刷新」写成<strong>控制器义务</strong>：间隔、与访存争用、对 CPU 呈现的多拍空洞。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>电荷泄漏给出保留时间 \\(t_{\\mathrm{REF}}\\)（温度越高越短）。\\(R\\) 行要在该时间内各刷新至少一次，平均间隔 \\(t_{\\mathrm{REF}}/R\\)。刷新：选一行，读到灵敏放大器，写回——与破坏性读同一套。缺口不是新的单元物理，而是：刷新命令与 CPU 的激活/预充电抢行，控制器要仲裁。</p><p>SRAM 交叉耦合不刷新。把主存当组合 ROM 的单周期图，把这一格藏掉了。</p><h3 id="刷新不是「定期-dump-到磁盘」" tabindex="-1">刷新不是「定期 dump 到磁盘」 <a class="header-anchor" href="#刷新不是「定期-dump-到磁盘」" aria-label="Permalink to &quot;刷新不是「定期 dump 到磁盘」&quot;">​</a></h3><p>不是交换、不是断电保存。是阵列内部的读-回写，掉电仍丢。把 refresh 理解成 checkpoint，后课闪存的非易失会对不齐。</p><p><span class="marginnote">Harris 强调保留时间。Patterson/Hennessy 把 DRAM 延迟与控制器放进性能。JEDEC 的 \\(t_{\\mathrm{REFI}}\\) 是工程定额，本课只取「行遍历周期」这一层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集中刷新：停访存、扫完全部行。分散刷新：穿插在命令流里。自刷新：空闲时 DRAM 内部计数。CPU 侧看到的是偶发额外延迟，不是每个 <code>lw</code> 都刷新。</p>',11)),(e(),B(i,null,{default:E(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAK%5B%22%E7%94%B5%E5%AE%B9%E6%B3%84%E6%BC%8F%22%5D%20--%3E%20TIME%5B%22%E4%BF%9D%E7%95%99%E6%97%B6%E9%97%B4%E5%86%85%E6%89%AB%E8%A1%8C%22%5D%0A%20%20TIME%20--%3E%20CMD%5B%22%E5%88%B7%E6%96%B0%E5%91%BD%E4%BB%A4%E4%B8%8E%E8%AE%BF%E5%AD%98%E4%BB%B2%E8%A3%81%22%5D%0A%20%20CMD%20--%3E%20CPU%5B%22CPU%20%E7%9C%8B%E5%88%B0%E5%81%B6%E5%8F%91%E5%A4%9A%E6%8B%8D%22%5D%0A%20%20CPU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9D%9E%E6%98%93%E5%A4%B1%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[r("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"后课单周期教材仍可把数据存储器画成一拍；组成主干记得真实 DRAM 有刷新与打开行。纠错码可在刷新时顺带 scrub，本课不展开 ECC。温度补偿刷新是同一义务的参数，不是另一种存储。",-1)),(e(),B(i,null,{default:E(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20S1%5B%22%E9%9B%86%E4%B8%AD%E5%88%B7%E6%96%B0%EF%BC%9A%E4%B8%80%E6%AC%A1%E6%89%AB%E5%AE%8C%22%5D%0A%20%20%20%20B1%5B%22%E5%81%9C%E5%85%A8%E9%83%A8%E8%AE%BF%E5%AD%98%EF%BC%8C%E8%BF%9E%E7%BB%AD%E5%88%B7%E5%AE%8C%20R%20%E8%A1%8C%22%5D%20--%3E%20E1%5B%22%E9%95%BF%E9%98%BB%E5%A1%9E%EF%BC%8C%E4%B9%8B%E5%90%8E%E9%95%BF%E6%97%B6%E9%97%B4%E6%97%A0%E6%89%93%E6%89%B0%22%5D%0A%20%20end%0A%20%20subgraph%20S2%5B%22%E5%88%86%E6%95%A3%E5%88%B7%E6%96%B0%EF%BC%9A%E9%80%90%E8%A1%8C%E6%8F%92%E9%98%9F%22%5D%0A%20%20%20%20B2%5B%22%E6%AF%8F%20t_REF%2FR%20%E6%8F%92%E4%B8%80%E6%9D%A1%E5%88%B7%E6%96%B0%E5%91%BD%E4%BB%A4%22%5D%20--%3E%20E2%5B%22%E6%AF%8F%E6%AC%A1%E5%BB%B6%E8%BF%9F%E5%B0%8F%E8%80%8C%E5%9D%87%E5%8C%80%22%5D%0A%20%20end%0A%20%20subgraph%20S3%5B%22%E8%87%AA%E5%88%B7%E6%96%B0%EF%BC%9A%E5%BE%85%E6%9C%BA%E8%87%AA%E6%8C%81%22%5D%0A%20%20%20%20B3%5B%22DRAM%20%E5%86%85%E9%83%A8%E8%AE%A1%E6%95%B0%E5%99%A8%E8%87%AA%E9%A9%B1%22%5D%20--%3E%20E3%5B%22%E5%A4%96%E9%83%A8%E6%97%B6%E9%92%9F%E5%8F%AF%E5%81%9C%EF%BC%8C%E5%8A%9F%E8%80%97%E6%9C%80%E4%BD%8E%22%5D%0A%20%20end%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">数字实例：JEDEC 典型定额是 64 ms 内把全部行刷一遍。假设颗粒有 65536 行，平均每 \\(64\\,\\text{ms}/65536 \\approx 976\\,\\text{ns}\\) 就要刷一行；单次刷新占用几十纳秒，摊下来刷新大约吃掉 2-5% 的带宽——这就是「偶发多拍」的来源。</span></p><p><span class="marginnote">术语翻译：自刷新（self-refresh）就是「外部把时钟和数据线都断掉后，DRAM 芯片用内部自带的振荡器和计数器，自己按周期读出-写回每一行」。笔记本合盖待机时内存不失数据，靠的就是它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 DDR 突发时序表（那是<a href="/cs/dram-timing">DRAM 时序</a>一类后叶）、不讲 3D 堆叠。闪存的擦除/编程不是刷新。</p><p><span class="marginnote">常见误区：初学者容易把「refresh」理解成定期把内存 dump 到磁盘或做 checkpoint。实际上刷新只是把同一颗电容的电荷读出来再原样写回去，对象是阵列内部的比特，掉电照样全丢；它和持久化、交换（swap）没有任何关系。</span></p><p>后课默认：DRAM 正确性依赖刷新控制器；与 CPU 时钟可以不同源，为时钟域课留口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DRAM 必须在保留时间内刷新每一行。</li><li>刷新与访存争用，由控制器仲裁。</li><li>掉电不保存；SRAM 无此义务。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const R=o(p,[["render",m]]);export{f as __pageData,R as default};
